            a: "[কার্ড বানান](/create) চাপুন, আর কীভাবে বানাতে চান তা বেছে নিন। **কাস্টমাইজড**: কয়েকটা ছোট প্রশ্নের উত্তর দিন, বেশিরভাগই শুধু একটা ট্যাপে, আর আমরা আপনার উত্তর অনুযায়ী পুরো কার্ডটা একদম নতুন করে বানিয়ে দেব। **রেডিমেড ডিজাইন**: আমাদের {n}টি ডিজাইনের একটি বাছুন, ওই প্রশ্নগুলোরই কয়েকটার উত্তর দিন, আর আমরা তাতে আপনার কথাগুলো লিখে দেব। যেভাবেই বানান, **কার্টে যোগ করুন** চাপার আগে যা খুশি বদলে নিতে পারবেন।",
